<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {useMessage} from 'wot-design-uni'
import {closetApi,type ProcessingChoice} from '../../services/api'
import {batchApi,type IntakeBatch,type IntakeStrategy,type BatchTarget,type BatchSource,type Marker} from '../../services/batches'
import {useClosetStore} from '../../stores/closet'
import {useProcessingStore} from '../../stores/processing'
import {createUuid} from '../../domain/id'
import {eligible,freshSpriteTargets,restoreSpriteSelection,generationUnits} from '../../domain/intake'
import {batchIsProcessing,elapsedLabel} from '../../domain/waiting'
import type {Hint} from '../../services/quickIntake'
import AuthImage from '../AuthImage.vue'
import BatchTargetPreview from './BatchTargetPreview.vue'
import TargetMarker from './TargetMarker.vue'
import {choosePhotos,errorText,openAdd,openBatch,openGarment,settings} from './navigation'
const props=defineProps<{batchId?:string;embedded?:boolean}>(),closet=useClosetStore(),processingStore=useProcessingStore(),message=useMessage('batch')
const batch=ref<IntakeBatch>(),strategy=ref<IntakeStrategy>('SMART'),photos=ref<{path:string;name:string;key:string}[]>([]),markers=ref<Marker[]>([]),markSource=ref<BatchSource>(),busy=ref(false),loading=ref(true),error=ref(''),uploadIndex=ref(0),uploadProgress=ref(0),generationChoice=ref(''),recognitionChoice=ref(''),generationChoices=ref<ProcessingChoice[]>([]),recognitionChoices=ref<ProcessingChoice[]>([]),quotaLeft=ref<number|null>(null),quotaLimit=ref<number|null>(null),history=ref<IntakeBatch[]>([]),trial=ref('逐件整理'),resultTab=ref(false),comparison=ref<BatchTarget>(),sourceOpen=ref(false),selected=ref<string[]>([]),groupSize=ref(2),baseline=ref<Record<string,string>>({}),now=ref(Date.now()),help=ref(false)
let alive=true,polling=false,timer:ReturnType<typeof setTimeout>|undefined,clock:ReturnType<typeof setInterval>|undefined
const active=computed(()=>!!batch.value&&batchIsProcessing(batch.value)),locked=computed(()=>busy.value||active.value),trialEnabled=computed(()=>trial.value==='合图试用'),pending=computed(()=>batch.value?.targets.filter(t=>!t.confirmed&&t.status==='DETECTED'&&eligible(t.visibleFraction,t.keyDetailsVisible,batch.value!.strategy))||[]),results=computed(()=>batch.value?.targets.filter(t=>eligible(t.visibleFraction,t.keyDetailsVisible,batch.value!.strategy))||[]),skipped=computed(()=>batch.value?.targets.filter(t=>!eligible(t.visibleFraction,t.keyDetailsVisible,batch.value!.strategy))||[]),candidates=computed(()=>results.value.filter(t=>!t.confirmed)),fresh=computed(()=>freshSpriteTargets(candidates.value)),choosing=computed(()=>trialEnabled.value&&!active.value&&!resultTab.value&&!!candidates.value.length),incomplete=computed(()=>!!batch.value&&photos.value.length>batch.value.sources.length)
const detectionUnits=computed(()=>strategy.value==='MANUAL'?new Set(markers.value.map(m=>m.sourceId)).size:batch.value?.sources.length||photos.value.length)
const startReason=computed(()=>loading.value?'正在准备整理服务…':!recognitionChoice.value||!generationChoice.value?'整理服务尚未配置，请到设置中检查服务。':quotaLeft.value===null?'暂时无法读取今日额度，请重试。':strategy.value==='MANUAL'&&batch.value&&!markers.value.length?'点击照片中想收的衣物，再开始整理。':quotaLeft.value<detectionUnits.value?`今日剩余 ${quotaLeft.value} 次，不够处理这些照片。可以减少照片或明天继续。`:'')
const requests=computed(()=>generationUnits(selected.value.length,groupSize.value)),reworkCount=computed(()=>candidates.value.filter(t=>selected.value.includes(t.id)&&t.outputUrl).length),spriteBlocked=computed(()=>candidates.value.length<2?'合图至少需要两件可整理衣物，请返回逐件整理。':!selected.value.length?'选择想整理的衣物。':!generationChoice.value?'整理服务尚未配置。':quotaLeft.value===null?'正在读取额度。':requests.value>quotaLeft.value?`需要 ${requests.value} 次额度，今日剩余 ${quotaLeft.value} 次。可以减少选择，或增加每次件数。`:'')
const waitingTime=computed(()=>batch.value?elapsedLabel(Math.max(batch.value.createdAtMs,...batch.value.calls.map(c=>c.startedAtMs)),now.value):''),pendingQuotaText=computed(()=>quotaLeft.value!==null&&quotaLeft.value<pending.value.length?` , 今日剩余 ${quotaLeft.value} 次额度`:'')
const label:Record<string,string>={UPLOADED:'照片已保存',RECOGNIZING:'正在寻找照片里的衣物',DETECTED:'等待继续整理',GENERATING:'正在整理衣物',NEEDS_REVIEW:'核对后收进衣柜',QUEUED:'等待处理',RUNNING:'整理中',SUCCEEDED:'可以核对',SKIPPED:'需要补拍',FAILED:'这件没有完成',UNKNOWN:'需要核查结果',CANCELLED:'已取消'}
function storageKey(action:string){return `closet-batch:${closet.user?.username}:${batch.value!.id}:${action}`}
function key(action:string){const name=storageKey(action);let value=uni.getStorageSync(name);if(!value){value=createUuid();uni.setStorageSync(name,value)}return String(value)}
function persist(){if(!batch.value)return;uni.setStorageSync(storageKey('markers'),JSON.stringify(markers.value));uni.setStorageSync(storageKey('trial'),trialEnabled.value);uni.setStorageSync(storageKey('baseline'),JSON.stringify(baseline.value));uni.setStorageSync(storageKey('sprite-selection'),JSON.stringify({groupSize:groupSize.value,ids:selected.value}))}
watch([markers,trial,selected,groupSize],persist,{deep:true});watch(batch,value=>{if(value)processingStore.trackBatch(value,false,true)});watch(active,(value,previous)=>{if(previous&&!value)resultTab.value=true})
function model(value:string){return JSON.parse(value||'{}') as {provider?:string;model?:string}}
function source(target:BatchTarget){return batch.value?.sources.find(s=>s.id===target.sourceId)}
async function quota(){const q=await closetApi.quota();quotaLeft.value=Math.max(0,q.limit-q.used);quotaLimit.value=q.limit}
async function reloadQuota(){try{await quota();error.value=''}catch{error.value='额度读取失败，请稍后重试。'}}
async function accept(from:'album'|'camera'){if(locked.value||batch.value)return;try{const files=await choosePhotos(from,from==='camera'?1:Math.min(9,10-photos.value.length));for(const file of files){if(photos.value.length>=10){error.value='一次最多选择 10 张照片。';break}if(file.size>50*1024*1024){error.value='每张照片最多 50 MB，请导出较小照片后再试。';continue}const info=await uni.getImageInfo({src:file.tempFilePath}) as {type?:string};if(!['jpeg','jpg','png'].includes(info.type||'')){error.value='请选择 JPEG 或 PNG。HEIC 请先导出 JPEG，也可以直接拍照。';continue}photos.value.push({path:file.tempFilePath,name:file.tempFilePath.split('/').pop()||'照片',key:createUuid()})}}catch(e){error.value=errorText(e)}}
async function marked(hint?:Hint){if(!markSource.value||!batch.value)return;if(hint){if(markers.value.length>=10){error.value='一次最多标记 10 件衣物。';return}markers.value.push({sourceId:markSource.value.id,x:hint.x+(hint.width||0)/2,y:hint.y+(hint.height||0)/2})}markSource.value=undefined;persist()}
async function poll(){clearTimeout(timer);if(!batch.value||!alive||polling)return;polling=true;try{const value=await batchApi.get(batch.value.id);if(alive){batch.value=value;await quota();error.value=''}}catch(e){if(alive)error.value=errorText(e,'暂时无法读取进度，请稍后重试。')}finally{polling=false;if(alive)timer=setTimeout(poll,active.value?2000:10000)}}
async function submitStart(){if(!batch.value)return;batch.value=await batchApi.start(batch.value.id,key('start'),markers.value,model(recognitionChoice.value),model(generationChoice.value),trialEnabled.value);processingStore.trackBatch(batch.value,true);await quota()}
async function upload(){if(!photos.value.length||locked.value||startReason.value)return;busy.value=true;error.value='';try{for(let i=batch.value?.sources.length||0;i<photos.value.length;i++){const item=photos.value[i]!;uploadIndex.value=i+1;uploadProgress.value=0;batch.value=i===0?await batchApi.create(item.path,item.key,'MULTIPLE',strategy.value,p=>uploadProgress.value=p):await batchApi.append(item.path,batch.value!.id,item.key,p=>uploadProgress.value=p)}persist();if(strategy.value!=='MANUAL')await submitStart();if(props.embedded)uni.redirectTo({url:'/pkg-closet/batch/index?id='+encodeURIComponent(batch.value!.id)})}catch(e){error.value=errorText(e,'上传未完成，照片已保留，可继续上传。')}finally{busy.value=false;uploadIndex.value=0;if(alive)void poll()}}
async function startSaved(){if(locked.value||startReason.value)return;busy.value=true;error.value='';try{await submitStart()}catch(e){error.value=errorText(e,'整理未提交，照片已保存，请重试。')}finally{busy.value=false;void poll()}}
async function generate(ids:string[],retry=false,size=1){if(!batch.value||!ids.length||locked.value||quotaLeft.value===null||generationUnits(ids.length,size)>quotaLeft.value||!generationChoice.value)return;const existing=batch.value.targets.filter(t=>ids.includes(t.id)&&t.outputUrl);if(existing.length){try{await message.confirm({title:`重新整理 ${existing.length} 件已有结果的衣物？`,msg:`本次使用 ${generationUnits(ids.length,size)} 次额度。原图和已有结果保留，生成后请对照原图核对。`,confirmButtonText:'提交真实任务'})}catch{return}}busy.value=true;error.value='';try{existing.forEach(t=>baseline.value[t.id]=t.outputUrl!);persist();const action=retry?`retry-${createUuid()}`:`continue-${ids.join(',')}-${size}-${generationChoice.value}`;batch.value=await batchApi.generate(batch.value.id,key(action),{targetIds:ids,groupSize:size,referenceSide:1024,sizePolicy:'FIXED',quality:'low',...model(generationChoice.value)});processingStore.trackBatch(batch.value,true);selected.value=selected.value.filter(id=>!ids.includes(id));persist();resultTab.value=false;await quota()}catch(e){error.value=errorText(e,'整理未提交，识别结果已保存。')}finally{busy.value=false;void poll()}}
async function resumeLocal(call:string){if(!batch.value||locked.value)return;busy.value=true;try{batch.value=await batchApi.resumeLocal(batch.value.id,call)}catch(e){error.value=errorText(e,'暂未完成，整理图已保留。')}finally{busy.value=false;void poll()}}
function review(t:BatchTarget){if(!t.garmentId)return;openGarment(t.garmentId,t.jobId,batch.value?.id);comparison.value=undefined}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(i=>i!==id):[...selected.value,id]}
function selectAll(){selected.value=fresh.value.every(t=>selected.value.includes(t.id))?[]:fresh.value.map(t=>t.id)}
function firstGroup(){selected.value=fresh.value.slice(0,groupSize.value).map(t=>t.id)}
async function init(){loading.value=true;const loaded=await Promise.allSettled([closetApi.processingChoices(),batchApi.history(),quota(),props.batchId?batchApi.get(props.batchId):Promise.resolve(undefined)]);if(!alive)return;const [choices,recent,q,current]=loaded;if(choices.status==='fulfilled'){generationChoices.value=choices.value.generation;recognitionChoices.value=choices.value.recognition;generationChoice.value=choices.value.generation[0]?.value||'';recognitionChoice.value=choices.value.recognition[0]?.value||''}if(recent.status==='fulfilled')history.value=recent.value;if(q.status==='rejected')error.value='额度读取失败，请稍后重试。';if(current.status==='fulfilled'&&current.value){batch.value=current.value;strategy.value=batch.value.strategy;try{trial.value=uni.getStorageSync(storageKey('trial'))?'合图试用':'逐件整理';const saved=JSON.parse(uni.getStorageSync(storageKey('sprite-selection'))||'{}');groupSize.value=Math.max(2,Math.min(10,Number(saved.groupSize)||2));selected.value=restoreSpriteSelection(saved.ids,candidates.value);markers.value=(JSON.parse(uni.getStorageSync(storageKey('markers'))||'[]') as Marker[]).filter(m=>batch.value!.sources.some(s=>s.id===m.sourceId)&&Number.isFinite(m.x)&&Number.isFinite(m.y)&&m.x>=0&&m.y>=0&&m.x<=1&&m.y<=1).slice(0,10);baseline.value=JSON.parse(uni.getStorageSync(storageKey('baseline'))||'{}')}catch{markers.value=[]}}else if(current.status==='rejected')error.value=errorText(current.reason,'无法读取这次录入。');loading.value=false;void poll()}
onMounted(()=>{void init();clock=setInterval(()=>now.value=Date.now(),1000)});onShow(()=>{alive=true;if(batch.value)void poll()});onHide(()=>{alive=false;clearTimeout(timer)});onUnmounted(()=>{alive=false;clearTimeout(timer);clearInterval(clock)})
</script>
<template><view class="batch-intake">
 <view v-if="!embedded||batch&&batch.status!=='UPLOADED'" class="steps"><text>选照片</text><text>→ {{trialEnabled?'选衣物':'自动整理'}}</text><text>→ 整理结果</text></view>
 <wd-notice-bar v-if="error||batch?.error" class="notice" :text="error||batch?.error||''" :scrollable="false" wrapable/>
 <wd-skeleton v-if="loading" :row-col="[1,1,{height:'300rpx'},1]" animation="gradient"/>
 <template v-else-if="!batch||batch.status==='UPLOADED'">
 <view class="section"><text class="section-title">{{photos.length?`已选 ${photos.length} 张照片`:'把想收的衣物拍下来'}}</text><text v-if="!batch" class="subtitle">单件照、多件同框或自拍都可以，也能一次选多张。</text><view v-if="!batch" class="actions"><wd-button :disabled="locked||photos.length>=10" @click="accept('album')">{{photos.length?'继续选照片':'选择照片'}}</wd-button><wd-button plain :disabled="locked||photos.length>=10" @click="accept('camera')">拍照 / 自拍</wd-button></view>
 <view v-for="(photo,index) in !batch?photos:[]" :key="photo.key" class="photo"><view class="preview"><AuthImage :src="photo.path"/></view><view class="row"><text class="hint">{{photo.name}}</text><wd-button size="small" type="text" :disabled="locked" @click="photos.splice(index,1)">移除</wd-button></view></view>
 <template v-for="item in batch?.sources||[]" :key="item.id"><view class="preview"><AuthImage :src="item.previewUrl" :width="960" previewable/></view><text class="hint">{{item.name}}</text><view v-if="strategy==='MANUAL'" class="actions"><wd-button size="small" plain :disabled="locked" @click="markSource=item">点击指定要收的衣物</wd-button><wd-button v-for="(marker,index) in markers.filter(m=>m.sourceId===item.id)" :key="index" size="small" type="text" :disabled="locked" @click="markers=markers.filter(m=>m!==marker)">移除标记 {{index+1}}</wd-button></view></template>
 <view v-if="busy&&uploadIndex"><text class="hint">第 {{uploadIndex}} 张 · {{uploadProgress}}%</text><wd-progress :percentage="uploadProgress"/></view><text class="subtitle">{{strategy==='SMART'?'遮挡较多的衣物会跳过，优先保留真实细节。':strategy==='FULL'?'也会整理遮挡衣物，补全内容会标注推测。':'保存照片后，点击你想收的衣物。'}}</text><text class="hint">最多 10 张 · 每张 50 MB · JPEG / PNG</text></view>
 <view class="section"><view class="row"><text class="section-title">整理方式</text><wd-button type="text" size="small" @click="help=true">用量说明</wd-button></view><wd-segmented v-model:value="trial" :options="['逐件整理','合图试用']" :disabled="locked"/><text class="subtitle">{{trialEnabled?'先识别，再选择衣物与每组件数':'识别后自动分别整理衣物'}}</text><wd-picker v-if="!batch" v-model="strategy" :disabled="locked" label="有遮挡，或只想收其中几件？" :columns="[{value:'SMART',label:'只整理细节清楚的衣物（推荐）'},{value:'FULL',label:'遮挡的衣物也整理，缺失部分由模型推测'},{value:'MANUAL',label:'由我点击指定要收的衣物'}]"/><wd-picker v-model="recognitionChoice" label="识图模型" :columns="recognitionChoices" :disabled="locked"/><wd-picker v-model="generationChoice" label="图片模型" :columns="generationChoices" :disabled="locked"/></view>
 <text class="subtitle">{{trialEnabled?'选择照片后先识别，再选择衣物与分组。读取每张照片占 1 次，整理按所选组数计算。':'选择照片后先识别，再按实际衣物数量整理。每次读取、每件整理各占 1 次额度。'}}</text><text v-if="startReason" class="hint">{{startReason}}</text><view class="actions"><wd-button v-if="!batch||incomplete" block :loading="busy" :disabled="locked||!photos.length||!!startReason" @click="upload">{{incomplete?'继续上传':strategy==='MANUAL'?'保存照片，选择衣物':trialEnabled?'先识别衣物，再选择合图数量':photos.length?`开始整理 ${photos.length} 张照片`:'选择照片后开始整理'}}</wd-button><wd-button v-else block :loading="busy" :disabled="locked||!!startReason" @click="startSaved">{{trialEnabled?'识别目标，再选择合图数量':strategy==='MANUAL'?`整理标记的 ${markers.length} 件衣物`:'开始整理这些照片'}}</wd-button></view>
 </template>
 <template v-else-if="batch">
 <view class="heading"><text class="title">{{choosing?'选择衣物':active?(batch.status==='RECOGNIZING'?'正在寻找照片里的衣物':'正在整理衣物'):resultTab?'整理结果':pending.length?'已找到衣物，继续整理即可':label[batch.status]||'查看整理结果'}}</text><text class="subtitle">{{active?'可以离开页面，处理会继续。回来后在最近录入中查看结果。':`来自 ${batch.sources.length} 张照片 · ${batch.metrics?.confirmed||0} 件已入柜`}}</text><wd-button type="text" @click="openAdd('multiple')">添加新照片</wd-button></view>
 <view v-if="!trialEnabled&&!active&&pending.length" class="section"><text class="subtitle">还有 {{pending.length}} 件等待整理{{pendingQuotaText}}。</text><view class="actions"><wd-button v-if="Math.min(pending.length,quotaLeft||0)&&generationChoice" :disabled="locked" @click="generate(pending.slice(0,Math.min(pending.length,quotaLeft||0)).map(t=>t.id))">继续整理 {{Math.min(pending.length,quotaLeft||0)}} 件 · {{Math.min(pending.length,quotaLeft||0)}} 次额度</wd-button><text v-else class="hint">{{quotaLeft===null?'额度暂未读取成功。':!generationChoice?'整理服务尚未配置，请检查设置。':'今日额度已用完，结果已保存，明天可以继续。'}}</text></view></view>
 <view v-if="!active&&results.length" class="section"><wd-segmented v-model:value="trial" :options="['逐件整理','合图试用']" :disabled="locked"/><view class="actions"><wd-button v-if="trialEnabled&&candidates.length" plain size="small" @click="resultTab=!resultTab">{{resultTab?'选择衣物':'查看已有结果'}}</wd-button><wd-button plain size="small" @click="sourceOpen=true">查看来源照片</wd-button></view></view>
 <view v-if="active" class="section processing"><wd-loading/><text class="section-title">{{batch.status==='RECOGNIZING'?'正在识别衣物':'正在整理衣物'}}</text><text class="subtitle">已等待 {{waitingTime}} · {{batch.targets.filter(t=>t.outputUrl&&['SUCCEEDED','NEEDS_REVIEW'].includes(t.status)).length}} / {{batch.targets.length}} 件已有结果</text><text class="subtitle">处理会在后台继续，完成后会在站内提醒。</text><text class="hint">{{trialEnabled?'合图整理':'逐件整理'}} → 拆分衣物 → 去背景与制作贴纸</text></view>
 <view v-if="choosing" class="section"><view class="row"><text class="section-title">合图试用 · 已开启</text><wd-button type="text" size="small" @click="help=true">说明</wd-button></view><wd-picker v-model="groupSize" label="每组件数" :columns="Array.from({length:9},(_,i)=>({value:i+2,label:`${i+2} 件`}))" :disabled="locked"/><text class="hint">当前可整理 {{candidates.length}} 件，最多每组 10 件。</text><view class="actions"><wd-button size="small" plain :disabled="locked||!fresh.length" @click="firstGroup">只选一组</wd-button><wd-button size="small" plain :disabled="locked||!fresh.length" @click="selectAll">{{fresh.length&&fresh.every(t=>selected.includes(t.id))?'清空选择':`全选未处理 ${fresh.length} 件`}}</wd-button></view>
 <view v-for="target in candidates" :key="target.id" class="choice" @tap="toggle(target.id)"><BatchTargetPreview :target="target" :source="source(target)" processed/><view><wd-checkbox :model-value="selected.includes(target.id)" :disabled="locked">#{{batch.targets.findIndex(t=>t.id===target.id)+1}} {{target.recognition.target.description}}</wd-checkbox><text class="hint">{{selected.includes(target.id)?`第 ${Math.floor(candidates.filter(t=>selected.includes(t.id)).findIndex(t=>t.id===target.id)/groupSize)+1} 组 · 第 ${candidates.filter(t=>selected.includes(t.id)).findIndex(t=>t.id===target.id)%groupSize+1} 格`:target.outputUrl?'已有结果 · 选中将重做':'未选择'}}</text></view></view>
 <text class="subtitle">{{selected.length}} 件 → {{requests}} 组 → {{requests}} 次额度</text><text class="hint">提交后自动合图、拆分、去背景并制作贴纸</text><text v-if="reworkCount" class="hint">已选 {{reworkCount}} 件已有结果的衣物，将再次整理并使用额度。</text><text v-if="spriteBlocked" class="hint">{{spriteBlocked}}</text><view class="actions"><wd-button plain @click="resultTab=true">返回</wd-button><wd-button :disabled="locked||!!spriteBlocked" @click="generate(candidates.filter(t=>selected.includes(t.id)).map(t=>t.id),true,groupSize)">{{reworkCount?'合图重做':'合图整理'}} {{selected.length}} 件 · {{requests}} 次</wd-button></view></view>
 <template v-if="!choosing&&!active"><text class="subtitle">{{results.filter(t=>t.outputUrl).length}} 件已有结果 · {{pending.length}} 件等待整理</text><text class="hint">处理完成后仍需确认入柜</text><view v-for="target in results" :key="target.id" class="section"><view class="choice"><BatchTargetPreview :target="target" :source="source(target)" processed/><view><text>#{{batch.targets.findIndex(t=>t.id===target.id)+1}} {{target.recognition.target.description}}</text><text class="hint">{{target.confirmed?'已入柜':['FAILED','UNKNOWN'].includes(target.status)?label[target.status]:target.outputUrl?'已有结果 · 尚未入柜':label[target.status]||'等待整理'}}</text></view></view><view v-if="target.completion" class="tags"><wd-tag type="warning">含推测补全 · 请对照原图</wd-tag></view><view class="actions"><wd-button v-if="target.jobId&&!['QUEUED','RUNNING'].includes(target.status)" size="small" @click="review(target)">查看结果</wd-button><wd-button v-else-if="!target.confirmed&&target.status==='DETECTED'" size="small" :disabled="locked||!quotaLeft||!generationChoice" @click="generate([target.id])">整理这件 · 1 次</wd-button><wd-button size="small" plain @click="comparison=target">对照原图</wd-button><wd-button v-if="!target.confirmed&&['FAILED','UNKNOWN','SUCCEEDED','NEEDS_REVIEW'].includes(target.status)" type="text" size="small" :disabled="locked||!quotaLeft||!generationChoice" @click="generate([target.id],true)">重做这件 · 1 次额度</wd-button></view></view><wd-status-tip v-if="!batch.targets.length" image="content" tip="没有找到适合整理的衣物。补拍清楚后再添加照片。"/></template>
 <view v-if="skipped.length" class="section"><text class="section-title">{{skipped.length}} 件暂未整理 · 建议补拍</text><view v-for="target in skipped" :key="target.id" class="field-row"><text>{{target.recognition.target.description}}</text><text class="subtitle">{{target.reason||'可见细节不足，补拍完整衣物效果更好。'}}</text><wd-button type="text" @click="comparison=target">查看原图</wd-button></view></view>
 <view v-for="call in batch.calls.filter(c=>c.atlasUrl&&['FAILED','UNKNOWN'].includes(c.status))" :key="call.id" class="section"><text class="subtitle">整理图已经保存，后续图片处理未完成。</text><wd-button :disabled="locked" @click="resumeLocal(call.id)">继续图片处理 · 不占额度</wd-button></view>
 <wd-collapse v-if="batch.calls.length"><wd-collapse-item title="查看本次用量" name="costs"><text class="subtitle">识别 {{batch.calls.filter(c=>c.type==='RECOGNIZE'&&c.status!=='SKIPPED').length}} 次 · 整理 {{batch.calls.filter(c=>c.type==='GENERATE').length}} 次 · 重做 {{batch.calls.filter(c=>c.type==='REWORK').length}} 次</text><text class="hint">已知费用 ${{batch.calls.reduce((sum,c)=>sum+(c.costUsd||0),0).toFixed(5)}}{{batch.calls.some(c=>c.costUsd===null)?'；部分调用金额未知，等待计费明细。':''}}</text><view v-for="call in batch.calls" :key="call.id" class="field-row"><text>{{call.type}} · {{call.model}} · {{call.status}}</text><text v-if="call.error" class="hint">{{call.error}}</text></view></wd-collapse-item></wd-collapse>
 </template>
 <text class="hint">今日剩余 {{quotaLeft===null?'暂未读取':quotaLeft}} / {{quotaLimit??'—'}} 次额度</text><view class="actions"><wd-button v-if="quotaLeft===null&&!loading" type="text" size="small" @click="reloadQuota">重试读取额度</wd-button><wd-button v-if="!generationChoice||!recognitionChoice" type="text" size="small" @click="settings">检查设置</wd-button><wd-button v-if="error&&batch" type="text" size="small" @click="poll">重试刷新</wd-button><wd-button v-if="error&&!batch" type="text" size="small" @click="init">重试</wd-button></view>
 <view v-if="history.length&&!batchId" class="section"><text class="section-title">最近录入</text><wd-cell v-for="item in history.slice(0,5)" :key="item.id" :title="`${item.sources.length} 张照片 · ${label[item.status]||'查看结果'}`" :value="new Date(item.createdAtMs).toLocaleDateString()" is-link @click="openBatch(item.id)"/></view>
 <wd-popup v-model="sourceOpen" position="bottom" closable><view class="sheet"><text class="sheet-title">来源照片</text><view v-for="item in batch?.sources||[]" :key="item.id"><view class="preview"><AuthImage :src="item.originalUrl||item.previewUrl" :width="960" previewable/></view><text class="hint">{{item.name}} · 点击查看原始大图</text></view></view></wd-popup>
 <wd-popup :model-value="!!comparison" position="bottom" closable @close="comparison=undefined"><view v-if="comparison" class="sheet"><text class="sheet-title">{{baseline[comparison.id]?'原图与试用前后对比':'对照原图'}}</text><text class="subtitle">原照片</text><view class="preview"><AuthImage :src="source(comparison)?.originalUrl||source(comparison)?.previewUrl" :width="960" previewable/></view><template v-if="comparison.outputUrl"><text class="subtitle">整理结果{{comparison.completion?' · 包含推测补全':''}}</text><view class="preview"><AuthImage :src="comparison.outputUrl" :width="960" previewable/></view></template><template v-if="baseline[comparison.id]"><text class="subtitle">试用前的整理结果</text><view class="preview"><AuthImage :src="baseline[comparison.id]" :width="960" previewable/></view></template><text v-if="comparison.reason" class="subtitle">{{comparison.reason}}</text><wd-button v-if="!comparison.confirmed&&comparison.jobId&&!['QUEUED','RUNNING'].includes(comparison.status)" @click="review(comparison)">核对并入柜</wd-button></view></wd-popup>
 <wd-popup :model-value="!!markSource" position="bottom" closable @close="markSource=undefined"><TargetMarker v-if="markSource" :src="markSource.previewUrl" @finish="marked" @close="markSource=undefined"/></wd-popup>
 <wd-popup v-model="help" position="bottom" closable><view class="sheet"><text class="sheet-title">用量与处理方式</text><text class="subtitle">读取照片每张 1 次额度。逐件整理每件 1 次；合图试用识别后由你选择衣物和分组，按实际组数计费。拆分、去背景及贴纸制作不占 AI 额度。</text><text class="subtitle">将选中的衣物按组整理，生成后自动拆分、去背景并制作贴纸。更多件数可能影响细节，请对照原图核对；已有结果重新整理会占用额度。</text><text class="hint">整理额度按选中件数除以每组件数向上取整，最后一组可以少于设定件数。</text></view></wd-popup><wd-message-box selector="batch"/>
</view></template>
<style lang="scss" scoped>@import './closet.scss';.steps{display:flex;justify-content:space-between;color:$muted;font-size:24rpx;padding:32rpx 0}.processing{text-align:center;padding-top:60rpx;padding-bottom:60rpx}.processing .section-title{margin-top:32rpx}.choice{display:flex;align-items:center;gap:24rpx;padding:20rpx 0}.choice>view:last-child{flex:1;min-width:0}.photo{margin:20rpx 0}.preview{height:450rpx}.batch-intake{margin-top:24rpx}</style>
